  "help.tabs.sessions":
    "Þ“Þ¬Þ„Þ¬Þ‡Þ°ÞŽÞ¦Þ‡Þ¨ Þ‡Þ§ ÞÞ¬ÞÞ¦Þ‚Þ¬Þ‡Þ° ÞŠÞ¦ÞÞ§ØŒ Þ‚ÞªÞˆÞ¦ÞŒÞ¦ ÞŒÞ¨Þ‰Þ§ÞŽÞ¬ Þ‡Þ¬Þ‡Þ°ÞˆÞ¬ÞÞ° Þ•Þ°ÞƒÞ®Þ–Þ¬Þ†Þ°Þ“Þ¦Þ†ÞªÞ‚Þ° Þ‰Þ¨Þ€Þ§ÞƒÞª Þ€ÞªÞƒÞ¨ ÞÞ¬ÞÞ¦Þ‚Þ¬Þ‡Þ° Þ€ÞªÞ…ÞªÞˆÞ§ÞÞ¬ÞˆÞ¬. Þ‡Þ§ Þ†Þ¦Þ‰Þ¬Þ‡Þ° ÞŠÞ¬ÞÞªÞ‰ÞªÞ‚Þ° Þ‡Þ§ Þ“Þ¬Þ„Þ¬Þ‡Þ° Þ€ÞªÞ…ÞªÞˆÞ§ØŒ Þ‡Þ¦Þ‹Þ¨ Þ‚Þ¨Þ‰ÞªÞ‰ÞªÞ‚Þ° Þ„Þ¦Þ‚Þ°Þ‹Þª Þ†ÞªÞƒÞ§ÞÞ¬ÞˆÞ¬.",
